WITNESS_GAP_TABLE = {
    2: 1, 3: 2, 4: 1, 5: 2, 6: 1, 7: 4, 8: 3, 9: 2, 10: 1,
    11: 2, 12: 1, 13: 4, 14: 3, 15: 2, 16: 1, 17: 2, 18: 1,
    19: 4, 20: 3, 21: 2, 22: 1, 23: 6, 24: 5, 25: 4, 26: 3,
    27: 2, 28: 1, 29: 2, 30: 1, 31: 6, 32: 5, 33: 4, 34: 3,
    35: 2, 36: 1, 37: 4, 38: 3, 39: 2, 40: 1
}

def is_prime(m):
    if m < 2:
        return False
    d = 2
    while d * d <= m:
        if m % d == 0:
            return False
        d += 1
    return True

def next_prime(n):
    m = n + 1
    while not is_prime(m):
        m += 1
    return m

def verify():
    result = True
    for n in range(2, 41):
        if WITNESS_GAP_TABLE[n] != next_prime(n) - n:
            result = False
    return result

RESULT = verify()
assert RESULT is True
